// above jit_above_cost (100,000), so PostgreSQL JIT-compiled 47 functions to serve
// 7 days of work: measured on 200k sends, 252 ms of JIT to wrap 26 ms of query.
// Aggregating up front keeps the estimate small, so no JIT fires, and each table is
// range-scanned once instead of once per day.
//
// UTC is stated EXPLICITLY on every day boundary (`AT TIME ZONE 'UTC'`) rather than
// letting Postgres widen a DATE with the session time zone: the whole product counts
// days in UTC (warmup_daily_stats.day, the daily caps, the campaign limit), and a
// server whose session TZ was not UTC would otherwise silently shift every bucket.
// The lower bounds stay plain comparisons against the bare column, so the
// (workspace_id, sent_at) and (campaign_id, stopped_at) indexes still range-seek.
//
// On the `bounced` CTE: the UNION already yields DISTINCT (day, contact) pairs, so
// COUNT(*) per day IS the distinct-contact count -- the two bounce feeds reporting
// one contact on one day collapse to one row. A contact that bounced via the poller
// on one day and via an ingested event on another counts once per day, which is
// what a per-day series means.
//
// NOTE: the parentheses around (@since::date)::timestamp are load-bearing. sqlc
// v1.31 mis-rewrites a bare @param with a CHAINED cast (@since::date::timestamp):
// it emits corrupt SQL -- observed eating the "GR" off a later GROUP BY -- and then
// reports the syntax error against an unrelated line in the file, which sends you
// looking in the wrong place. Parenthesising the first cast, or using
// sqlc.arg(since)::date::timestamp, both generate correctly. Bisected in isolation.
func (q *Queries) ListDeliverabilitySeries(ctx context.Context, arg ListDeliverabilitySeriesParams) ([]ListDeliverabilitySeriesRow, error) {
	rows, err := q.db.Query(ctx, listDeliverabilitySeries, arg.Since, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListDeliverabilitySeriesRow
	for rows.Next() {
		var i ListDeliverabilitySeriesRow
		if err := rows.Scan(
			&i.Day,
			&i.Delivered,
			&i.Bounced,
			&i.Complained,
			&i.SpamPlaced,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pauseCampaignForBreach = `-- name: PauseCampaignForBreach :execrows
UPDATE campaigns SET status = 'paused'
WHERE id = $1 AND workspace_id = $2 AND status = 'running'
`

type PauseCampaignForBreachParams struct {
	CampaignID  uuid.UUID `json:"campaign_id"`
	WorkspaceID uuid.UUID `json:"workspace_id"`
}

// The breaker's transition, guarded on status='running'. That guard is the
// exactly-once guarantee: a second evaluation of an already-paused campaign
// updates zero rows, so it records no second pause event. It reuses the existing
// 'paused' status rather than inventing a terminal state — an auto-paused
// campaign is a paused campaign, restartable the normal way.
func (q *Queries) PauseCampaignForBreach(ctx context.Context, arg PauseCampaignForBreachParams) (int64, error) {
	result, err := q.db.Exec(ctx, pauseCampaignForBreach, arg.CampaignID, arg.WorkspaceID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setCampaignGuardrails = `-- name: SetCampaignGuardrails :execrows
UPDATE campaigns
SET auto_pause_enabled    = $1,
    bounce_pause_pct      = $2::float8::numeric,
    complaint_pause_pct   = $3::float8::numeric,
    guardrails_enabled_at = CASE
        WHEN auto_pause_enabled = FALSE AND $1 = TRUE THEN now()
        ELSE guardrails_enabled_at
    END
WHERE id = $4 AND workspace_id = $5
`

type SetCampaignGuardrailsParams struct {
	AutoPauseEnabled  bool      `json:"auto_pause_enabled"`
	BouncePausePct    float64   `json:"bounce_pause_pct"`
	ComplaintPausePct float64   `json:"complaint_pause_pct"`
	CampaignID        uuid.UUID `json:"campaign_id"`
	WorkspaceID       uuid.UUID `json:"workspace_id"`
}

// Zero affected rows means the campaign is not this workspace's — the 404. The
// percentages are validated in the service (422) and CHECK-constrained here, so a
// caller bypassing Go still cannot store a threshold of 0.
//
// guardrails_enabled_at is re-stamped ONLY on an off→on transition, which closes
// the same trap the migration's DEFAULT now() closes: an operator who switches the
// breaker on today must not have it act on bounces from while it was off. The CASE
// reads the OLD row value (a Postgres UPDATE's SET expressions see the pre-update
// row), so turning it on twice does not keep pushing the floor forward and turning
// it OFF does not move the floor at all.
func (q *Queries) SetCampaignGuardrails(ctx context.Context, arg SetCampaignGuardrailsParams) (int64, error) {
	result, err := q.db.Exec(ctx, setCampaignGuardrails,
		arg.AutoPauseEnabled,
		arg.BouncePausePct,
		arg.ComplaintPausePct,
		arg.CampaignID,
		arg.WorkspaceID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
